async () => { const sleep=ms=>new Promise(r=>setTimeout(r,ms)); const g=document.querySelector('vaadin-grid'); const deleted=[];
for(let round=0;round<30;round++){ let target=null; let maxIdx=0;
 for(let i=0;i<300 && !target;i+=4){ g.scrollToIndex(i); await sleep(150); const cells=[...g.querySelectorAll('vaadin-grid-cell-content')].map(c=>c.innerText); for(let j=0;j<cells.length;j++){ if(cells[j].includes('@') && cells[j+1]==='Closed (lost)' && cells[j+2]==='Avaya Inc.'){ target=cells[j]; break; } } if(!cells.some(x=>x.includes('@')) ) break; }
 if(!target) break;
 const c=[...g.querySelectorAll('vaadin-grid-cell-content')].find(c=>c.innerText===target); c.click(); await sleep(600);
 const em=[...document.querySelectorAll('vaadin-email-field,vaadin-text-field')].map(f=>f.value); if(!em.includes(target)) return {error:'form mismatch',target,em,deleted};
 [...document.querySelectorAll('vaadin-button')].find(b=>b.innerText.trim()==='Delete').click(); await sleep(800); deleted.push(target);
}
return deleted}

